// never installed into the runtime and none of its text may authorize output.

export const SOURCE_DOCUMENT = "ANDREWS_TRANSCRIPTION_CANVAS.md";
export const SOURCE_LINE_START = 448;
export const SOURCE_LINE_END = 1393;
export const SOURCE_SHA256 =
  "b3e6e8918ca417f4254280cbcabc7967dcbb254683d037e0d8bde37f474f010d";

function claim({
  id,
  section,
  span,
  anchors,
  summary,
  kind,
  source,
  owners,
  role,
  disposition,
  conflict,
  proofs,
}) {
  return Object.freeze({
    id,
    section,
    lineStart: span[0],
    lineEnd: span[1],
    exactSourceAnchors: Object.freeze([...anchors]),
    summary,
    canonicalObjectKind: kind,
    existingTypedSource: source,
    sharedOperationOrInvariant: Object.freeze([...owners]),
    factRole: role,
    disposition,
    conflictingPath: conflict,
    proofIds: Object.freeze(["source-span-anchor", ...proofs]),
  });
}

